class TagStream(HTMLParser):
    """The tags of a document with every text node discarded.

    Deliberately a copy of the reader in `validate_article_translations.py`
    rather than an import: that script is a standalone psycopg tool, and this
    check has to run *before* the write, not after it.
    """

    def __init__(self) -> None:
        super().__init__(convert_charrefs=False)
        self.stream: list[tuple[str, tuple]] = []

    def handle_starttag(self, tag, attrs):
        self.stream.append((tag, tuple(sorted(attrs))))

    handle_startendtag = handle_starttag

    def handle_endtag(self, tag):
        self.stream.append(("/" + tag, ()))


# Lowercase words joined by single hyphens -- what the public route matches.
SLUG = re.compile(r"[a-z0-9]+(?:-[a-z0-9]+)*")


def tag_stream(html: str) -> list[tuple[str, tuple]]:
    parser = TagStream()
    parser.feed(html)
    parser.close()
    return parser.stream


