def target_database() -> str:
    """Which database this run will actually write to, host and name only.

    `Settings` reads `.env` relative to the working directory and falls back to
    a local SQLite file, so running this from the wrong directory writes nothing
    to Postgres and still reports success. Printing the target turns that silent
    no-op into something the operator can see before answering the prompt.
    """
    url = make_url(get_settings().database_url)
    where = url.host or "local file"
    return f"{url.drivername} -> {where}/{url.database}"


async def run(dry_run: bool, force: bool) -> int:
    print(f"database: {target_database()}\n")

    articles = {}
    async with AsyncSessionLocal() as session:
        rows = (
            (await session.execute(select(Article).where(Article.trash.is_(False))))
            .scalars()
            .all()
        )
        for article in rows:
            articles[article.slug] = article

        unknown = sorted(set(TRANSLATIONS) - set(articles))
        if unknown:
            print(f"error: no article matches these slugs: {', '.join(unknown)}")
            return 1

        # Seeded with every slug already spoken for in either column, per
        # category. The public lookup matches `slug` or `slug_en`, so an English
        # slug colliding with some *other* article's Indonesian slug would make
        # the URL ambiguous even though the unique index is satisfied.
        taken: dict[int | None, set[str]] = {}
        for article in articles.values():
            slugs = taken.setdefault(article.category_id, set())
            slugs.add(article.slug)
            if article.slug_en:
                slugs.add(article.slug_en)

        planned: list[Article] = []
        skipped = 0
        for slug, translation in TRANSLATIONS.items():
            article = articles[slug]
            if article.body_en and not force:
                skipped += 1
                continue

            # Checked for every row before any row is written, so a bad
            # translation cannot leave the batch half-applied.
            if tag_stream(translation["body"]) != tag_stream(article.body_id):
                print(f"error: tag stream differs from the Indonesian source: {slug}")
                return 1

            english = translation["slug"]
            if not SLUG.fullmatch(english):
                print(f"error: not a usable URL slug: {slug} -> {english}")
                return 1

            # Its own slugs are not competitors when re-running with --force.
            competitors = taken[article.category_id] - {article.slug, article.slug_en or ""}
            if english in competitors:
                print(f"error: English slug already used in this category: {english}")
                return 1
            taken[article.category_id].add(english)

            planned.append(article)
            if not dry_run:
                article.summary_en = translation["summary"]
                article.body_en = translation["body"]
                article.slug_en = english

        for article in planned:
            print(f"  article {article.id:>4}  {article.slug}")

        print(
            f"\n{len(planned)} articles to translate; {skipped} already have an English body; "
            f"{len(articles) - len(TRANSLATIONS)} articles are not in this batch"
        )

        if dry_run:
            print("dry run -- nothing written")
            return 0

        await session.commit()
        print("written")
        return 0


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--dry-run", action="store_true", help="report the plan, write nothing")
    parser.add_argument(
        "--force",
        action="store_true",
        help="overwrite rows that already have an English body",
    )
    args = parser.parse_args()
    return asyncio.run(run(args.dry_run, args.force))


if __name__ == "__main__":
    raise SystemExit(main())
